import { z } from 'zod';

const schema = z.object({
  name: z.string(),
  age: z.number(),
});

const result = schema.safeParse({ name: 42, age: 'old' });
if (!result.success) {
  // v4: use z.treeifyError() instead of error.format()
  const tree = z.treeifyError(result.error);
  console.log(tree); // nested error object

  // For a simple flat list:
  const flat = z.flattenError(result.error);
  console.log(flat.fieldErrors); // { name: ['...'], age: ['...'] }
}

