import { z } from 'zod';

const formSchema = z.object({
  email: z.email(),
  password: z.string().min(8),
});

const result = formSchema.safeParse({ email: 'invalid', password: 'short' });
if (!result.success) {
  // v4: z.flattenError() replaces error.flatten()
  const { fieldErrors, formErrors } = z.flattenError(result.error);
  console.log(fieldErrors); // { email: [...], password: [...] }
}

