import { z } from 'zod';

// v4: coerce schemas accept unknown input (not string)
const numSchema = z.coerce.number();
type Input = z.input<typeof numSchema>; // unknown
type Output = z.output<typeof numSchema>; // number

// This now works without type errors:
numSchema.parse(42);       // number input OK
numSchema.parse('42');     // string input coerced
numSchema.parse(null);     // null coerced
numSchema.parse(true);     // boolean coerced

console.log(numSchema.parse('3.14')); // 3.14

import { z } from 'zod';

// v4: .nonempty() behaves like .min(1) - inferred type is string[]
const schema = z.array(z.string()).nonempty();
type T = z.infer<typeof schema>; // string[] (not [string, ...string[]])

console.log(schema.parse(['a', 'b'])); // OK
try { schema.parse([]); } catch (e) { console.log('Empty array rejected'); }

// If you need the tuple type, use z.tuple with rest:
const tupleSchema = z.tuple([z.string()]).rest(z.string());
type TupleT = z.infer<typeof tupleSchema>; // [string, ...string[]]

import { z } from 'zod';

// v4: error param replaces message
const passwordSchema = z.string().min(8, { error: 'Password must be at least 8 characters' });

// Can also be a function:
const nameSchema = z.string().min(2, { error: (issue) => `Name too short: ${issue.minimum} chars required` });

console.log(passwordSchema.safeParse('short').error?.issues[0].message);

