import { z } from 'zod';

// v4: z.ZodTypeAny is no longer needed - use z.ZodType directly
function validate<T extends z.ZodType>(schema: T, value: unknown): z.infer<T> {
  return schema.parse(value);
}

function safeParse<T extends z.ZodType>(schema: T, value: unknown) {
  return schema.safeParse(value);
}

const result = validate(z.string(), 'hello');
console.log(result); // 'hello'

